<script setup lang="ts">
/**
 * Command-menu search over VitePress's local search index.
 *
 * `@localSearchIndex` is generated by VitePress itself whenever
 * `themeConfig.search.provider` is `'local'`, whatever the theme, so this
 * dialog only supplies the UI. The MiniSearch options mirror the default
 * theme's so ranking matches what VitePress users already get.
 *
 * Import this file only behind `__VP_LOCAL_SEARCH__` (see Layout.vue): the
 * virtual module does not exist when local search is off.
 */
import { computed, nextTick, ref, shallowRef, watch } from 'vue'
import { useData, useRouter } from 'vitepress'
import MiniSearch from 'minisearch'
import localSearchIndex from '@localSearchIndex'
import { DialogContent, DialogOverlay, DialogPortal, DialogRoot, DialogTitle, VisuallyHidden } from 'reka-ui'
import { motion } from 'motion-v'
import { CornerDownLeft, FileText, Hash, Search } from '@lucide/vue'
import { searchOpen } from '../composables/search'
import type { ThemeConfig } from '../types'

interface Doc {
  id: string
  title: string
  titles: string[]
}

const { localeIndex, theme } = useData<ThemeConfig>()
const router = useRouter()

const query = ref('')
const selected = ref(0)
const input = ref<HTMLInputElement>()
const list = ref<HTMLElement>()
const index = shallowRef<MiniSearch<Doc> | null>(null)

async function loadIndex() {
  if (index.value) return
  // Each locale's index is a lazy chunk; it is fetched the first time the dialog opens.
  const load = localSearchIndex[localeIndex.value] ?? localSearchIndex.root
  if (!load) return
  const { default: json } = await load()
  index.value = MiniSearch.loadJSON<Doc>(json, {
    fields: ['title', 'titles', 'text'],
    storeFields: ['title', 'titles'],
    searchOptions: { fuzzy: 0.2, prefix: true, boost: { title: 4, text: 2, titles: 1 } },
  })
}

const results = computed(() => {
  const q = query.value.trim()
  if (!q || !index.value) return []
  return (index.value.search(q) as unknown as Doc[]).slice(0, 12)
})

watch(results, () => {
  selected.value = 0
})

watch(searchOpen, async (open) => {
  if (!open) return
  await loadIndex()
  await nextTick()
  input.value?.focus()
})

function go(i = selected.value) {
  const hit = results.value[i]
  if (!hit) return
  searchOpen.value = false
  router.go(hit.id)
}

function move(step: number) {
  const n = results.value.length
  if (!n) return
  selected.value = (selected.value + step + n) % n
  nextTick(() => list.value?.querySelector('[data-selected="true"]')?.scrollIntoView({ block: 'nearest' }))
}

const placeholder = computed(() => theme.value.search?.options?.placeholder ?? 'Search documentation…')
</script>

<template>
  <DialogRoot v-model:open="searchOpen">
    <DialogPortal>
      <DialogOverlay class="cf-search-overlay fixed inset-0 z-[600] bg-black/40 backdrop-blur-[2px]" />
      <DialogContent
        class="cf-search-content fixed top-[12vh] left-1/2 z-[601] flex max-h-[70vh] w-[min(640px,calc(100vw-2rem))] -translate-x-1/2 flex-col overflow-hidden rounded-xl border bg-popover shadow-2xl"
        @keydown.down.prevent="move(1)"
        @keydown.up.prevent="move(-1)"
        @keydown.enter.prevent="go()"
      >
        <VisuallyHidden><DialogTitle>Search</DialogTitle></VisuallyHidden>
        <div class="flex items-center gap-3 border-b px-4">
          <Search class="size-4 shrink-0 text-muted-foreground" />
          <input
            ref="input"
            v-model="query"
            class="h-12 w-full bg-transparent text-[15px] outline-none placeholder:text-muted-foreground"
            :placeholder="placeholder"
            aria-label="Search"
            autocomplete="off"
            spellcheck="false"
          />
          <kbd class="rounded border px-1.5 py-0.5 font-mono text-[11px] text-muted-foreground">Esc</kbd>
        </div>

        <div ref="list" class="overflow-y-auto p-2" role="listbox">
          <p v-if="query && !results.length" class="px-3 py-8 text-center text-sm text-muted-foreground">
            No results for “{{ query }}”
          </p>
          <p v-else-if="!query" class="px-3 py-8 text-center text-sm text-muted-foreground">Type to search the docs</p>
          <a
            v-for="(hit, i) in results"
            :key="hit.id"
            :href="hit.id"
            role="option"
            :aria-selected="i === selected"
            :data-selected="i === selected"
            class="relative flex items-center gap-3 rounded-md px-3 py-2.5 text-sm"
            @click.prevent="go(i)"
            @pointermove="selected = i"
          >
            <motion.span
              v-if="i === selected"
              layout-id="cf-search-pill"
              class="absolute inset-0 rounded-md bg-accent"
              :transition="{ type: 'spring', stiffness: 1100, damping: 60, mass: 0.5 }"
            />
            <component :is="hit.id.includes('#') ? Hash : FileText" class="relative size-4 shrink-0 text-muted-foreground" />
            <span class="relative min-w-0 flex-1">
              <span v-if="hit.titles.length" class="block truncate text-xs text-muted-foreground">
                {{ hit.titles.join(' › ') }}
              </span>
              <span class="block truncate" v-html="hit.title" />
            </span>
            <CornerDownLeft v-if="i === selected" class="relative size-3.5 shrink-0 text-muted-foreground" />
          </a>
        </div>
      </DialogContent>
    </DialogPortal>
  </DialogRoot>
</template>

<style>
.cf-search-overlay[data-state='open'] {
  animation: cf-fade-in 0.15s ease-out;
}
.cf-search-overlay[data-state='closed'] {
  animation: cf-fade-out 0.12s ease-in;
}
.cf-search-content[data-state='open'] {
  animation: cf-pop-in 0.2s cubic-bezier(0.22, 1, 0.36, 1);
}
.cf-search-content[data-state='closed'] {
  animation: cf-pop-out 0.12s ease-in;
}
@keyframes cf-fade-in {
  from {
    opacity: 0;
  }
}
@keyframes cf-fade-out {
  to {
    opacity: 0;
  }
}
@keyframes cf-pop-in {
  from {
    opacity: 0;
    transform: translate(-50%, 8px) scale(0.97);
  }
}
@keyframes cf-pop-out {
  to {
    opacity: 0;
    transform: translate(-50%, 4px) scale(0.98);
  }
}
/* themeConfig.motion: 'off' always stills them, 'system' defers to the OS. */
:root[data-cf-motion='off'] :is(.cf-search-overlay, .cf-search-content) {
  animation: none !important;
}
@media (prefers-reduced-motion: reduce) {
  :root[data-cf-motion='system'] :is(.cf-search-overlay, .cf-search-content) {
    animation: none !important;
  }
}
</style>
